{"explanation":"A radian measures an angle by comparing the length of its circular arc to the circle’s radius: θ = arc length ÷ radius. One radian is the angle that makes the arc exactly as long as the radius—about 57.3°. Watch the yellow arc grow, then move the slider to compare the two lengths.","manimCode":"const radius = 1.8;
const center = [-2, 0.35, 0];
const angleTracker = new ValueTracker(0.15);
const pointAt = a => [center[0] + radius * Math.cos(a), center[1] + radius * Math.sin(a), 0];

const heading = new Text({ text: 'What is a radian?', fontSize: 36, color: WHITE });
heading.moveTo([0, 3.15, 0]);
const circle = new Circle({ radius, color: GRAY });
circle.moveTo(center);
circle.setStrokeWidth(2);
const fixedRadius = new Line({ start: center, end: pointAt(0), color: BLUE });
fixedRadius.setStrokeWidth(5);
const movingRadius = new Polygon({ vertices: [center, pointAt(0.15)], color: WHITE });
movingRadius.setFillOpacity(0);
movingRadius.setStrokeWidth(3);
const arc = new Polygon({ vertices: [pointAt(0), pointAt(0.15)], color: YELLOW });
arc.setFillOpacity(0);
arc.setStrokeWidth(7);
const wedge = new Polygon({ vertices: [center, pointAt(0), pointAt(0.15)], color: YELLOW });
wedge.setFill(YELLOW, 0.12);
wedge.setStrokeWidth(0);
const endpoint = new Dot({ point: pointAt(0.15), color: YELLOW });
const radiusLabel = new Text({ text: 'r', fontSize: 26, color: BLUE });
radiusLabel.moveTo([-1.1, 0.05, 0]);

const formula = new MathTex({ latex: '\\theta = \\frac{s}{r}', color: WHITE });
await formula.waitForRender();
formula.moveTo([2.8, 1.4, 0]);
const definition = new MathTex({ latex: 's = r \\quad \\Longrightarrow \\quad \\theta = 1\\,\\mathrm{rad}', color: YELLOW });
await definition.waitForRender();
definition.scale(0.8);
definition.moveTo([2.8, 0.35, 0]);
let readout = new Text({ text: '0.15 rad = 8.6 degrees', fontSize: 23, color: WHITE });
readout.moveTo([2.8, -0.6, 0]);

const rulerStart = [-3.8, -2.05, 0];
const arcRuler = new Polygon({ vertices: [rulerStart, [-3.8 + radius * 0.15, -2.05, 0]], color: YELLOW });
arcRuler.setFillOpacity(0);
arcRuler.setStrokeWidth(7);
const radiusRuler = new Line({ start: [-3.8, -2.55, 0], end: [-2, -2.55, 0], color: BLUE });
radiusRuler.setStrokeWidth(7);
const arcCaption = new Text({ text: 'Arc s', fontSize: 22, color: YELLOW });
arcCaption.moveTo([-4.75, -2.05, 0]);
const radiusCaption = new Text({ text: 'Radius r', fontSize: 22, color: BLUE });
radiusCaption.moveTo([-4.75, -2.55, 0]);
const footer = new Text({ text: 'One radian: the yellow and blue lengths match.', fontSize: 25, color: WHITE });
footer.moveTo([0, -3.25, 0]);

await scene.play(new Write(heading));
await scene.play(new Create(circle));
scene.add(wedge, fixedRadius, movingRadius, arc, endpoint, radiusLabel);
scene.add(formula, definition, readout, arcRuler, radiusRuler, arcCaption, radiusCaption, footer);

let previousValue = '';
function updateAngle() {
  const a = angleTracker.getValue();
  const arcPoints = [];
  for (let i = 0; i <= 90; i++) arcPoints.push(pointAt(a * i / 90));
  arc.setVertices(arcPoints);
  wedge.setVertices([center, ...arcPoints]);
  movingRadius.setVertices([center, pointAt(a)]);
  endpoint.moveTo(pointAt(a));
  arcRuler.setVertices([rulerStart, [-3.8 + radius * a, -2.05, 0]]);
  const value = a.toFixed(2) + ' rad = ' + (a * 180 / Math.PI).toFixed(1) + ' degrees';
  if (value !== previousValue) {
    scene.remove(readout);
    readout = new Text({ text: value, fontSize: 23, color: WHITE });
    readout.moveTo([2.8, -0.6, 0]);
    scene.add(readout);
    previousValue = value;
  }
}
endpoint.addUpdater(() => updateAngle());
await scene.play(angleTracker.animateTo(1));
await scene.wait(1.5);

const controls = new Controls(scene, { position: 'top-right', width: 260 });
controls.addSlider({ label: 'Angle (radians)', min: 0.15, max: 2.5, value: 1, step: 0.01, onChange: value => {
  angleTracker.setValue(value);
  updateAngle();
} });
controls.addButton({ label: 'Show exactly 1 radian', onClick: () => {
  angleTracker.setValue(1);
  updateAngle();
} });
await scene.wait(999999);"}

